// ── Every message, each way it goes ──────────────────────────────────────────

#[tokio::test]
async fn get_machine_request_is_sent() {
    for k in 0..2 {
        let request = samples::get_machine_request(k);
        let expected = on_wire::get_machine_request(k, false);

        let answer = ok(&wire::GetMachineResponse::default());
        let call = |client: Client| async move { client.get_machine(request).await };
        let (sent, response): (wire::GetMachineRequest, _) = exchange("GetMachine", answer, call).await;

        assert_eq!(sent, expected, "at k = {k}");
        assert_eq!(response.unwrap(), types::GetMachineResponse::default(), "at k = {k}");
    }
}

