// ── Errors ───────────────────────────────────────────────────────────────────

/// A call that fails as the fake says.
async fn failed(answer: Answer) -> Error {
    let call = |client: Client| async move { client.get_machine(types::GetMachineRequest::default()).await };
    let (_, response): (wire::GetMachineRequest, _) = exchange("GetMachine", answer, call).await;
    response.unwrap_err()
}

#[tokio::test]
async fn each_code_of_the_protocol_is_its_error_code() {
    let codes = [
        ("canceled", 499, ErrorCode::Canceled),
        ("unknown", 500, ErrorCode::Unknown),
        ("invalid_argument", 400, ErrorCode::InvalidArgument),
        ("deadline_exceeded", 504, ErrorCode::DeadlineExceeded),
        ("not_found", 404, ErrorCode::NotFound),
        ("already_exists", 409, ErrorCode::AlreadyExists),
        ("permission_denied", 403, ErrorCode::PermissionDenied),
        ("resource_exhausted", 429, ErrorCode::ResourceExhausted),
        ("failed_precondition", 400, ErrorCode::FailedPrecondition),
        ("aborted", 409, ErrorCode::Aborted),
        ("out_of_range", 400, ErrorCode::OutOfRange),
        ("unimplemented", 501, ErrorCode::Unimplemented),
        ("internal", 500, ErrorCode::Internal),
        ("unavailable", 503, ErrorCode::Unavailable),
        ("data_loss", 500, ErrorCode::DataLoss),
        ("unauthenticated", 401, ErrorCode::Unauthenticated),
    ];

    for (name, status, code) in codes {
        let error = failed(failure(name, status, &[], &STANDARD_NO_PAD)).await;

        assert_eq!(error.code(), code);
        assert_eq!(error.code().as_str(), name);
        assert_eq!(error.message(), MESSAGE);
        assert_eq!(error.to_string(), format!("{name}: {MESSAGE}"));
        assert!(error.details().is_empty(), "{name}");
    }
}

#[tokio::test]
async fn a_detail_the_crate_cannot_read_is_left_out() {
    let details: [(&str, &[u8]); 2] = [
        ("pethost.panel.v1.NoSuchDetailYet", b""),
        // A field 1 that says it is 127 bytes long, and ends there.
        ("pethost.panel.v1.ProjectBusy", b"\x0a\x7f"),
    ];
    let error = failed(failure("aborted", 409, &details, &STANDARD_NO_PAD)).await;

    assert_eq!(error.code(), ErrorCode::Aborted);
    assert!(error.details().is_empty(), "{:?}", error.details());
}

#[tokio::test]
async fn a_detail_is_read_with_padding_and_without() {
    // Three lengths in a row: base64 pads two of them.
    for length in 0..3 {
        let mut detail = wire::ProjectBusy::default();
        detail.__buffa_unknown_fields.push(buffa::UnknownField {
            number: 29,
            data: buffa::UnknownFieldData::LengthDelimited(vec![0; length]),
        });
        let detail = detail.encode_to_vec();

        for encode in [&STANDARD, &STANDARD_NO_PAD] {
            let answer = failure(
                "unavailable",
                503,
                &[("pethost.panel.v1.ProjectBusy", detail.as_slice())],
                encode,
            );
            assert_eq!(failed(answer).await.details().len(), 1, "{length} more bytes");
        }
    }
}

#[tokio::test]
async fn a_call_that_reaches_nothing_is_unavailable() {
    // Nothing listens where a listener just closed.
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let address = listener.local_addr().unwrap();
    drop(listener);

    let client = Client::with_base_url(TOKEN, &format!("http://{address}")).unwrap();
    let error = client
        .get_machine(types::GetMachineRequest::default())
        .await
        .unwrap_err();

    assert_eq!(error.code(), ErrorCode::Unavailable);
    assert!(std::error::Error::source(&error).is_some());
}

#[test]
fn a_base_url_that_is_none_is_refused() {
    for base_url in ["not a url", "console.pethost.dev", "ftp://console.pethost.dev"] {
        let error = Client::with_base_url(TOKEN, base_url).unwrap_err();
        assert_eq!(error.code(), ErrorCode::InvalidArgument, "{base_url}");
    }
}

/// `Client::new` is the client over HTTPS: the build of the checks has a second TLS provider
/// (the manifest says why), and making it must not ask rustls for the process's default one.
#[tokio::test]
async fn a_client_prints_without_its_token() {
    let printed = format!("{:?}", Client::new(TOKEN));

    assert!(printed.contains("https://console.pethost.dev"), "{printed}");
    assert!(!printed.contains(TOKEN), "{printed}");
}

/// A client is shared between tasks, and a call may be awaited on another thread.
#[tokio::test]
async fn a_client_and_its_calls_cross_threads() {
    fn shared<T: Clone + Send + Sync>() {}
    fn sent<T: Send>(_: &T) {}

    shared::<Client>();
    shared::<Error>();
    sent(&Client::new(TOKEN).get_machine(types::GetMachineRequest::default()));
}

// ── Time ─────────────────────────────────────────────────────────────────────

#[test]
fn a_time_prints_as_rfc_3339() {
    let print = |seconds, nanos| Timestamp { seconds, nanos }.to_string();

    assert_eq!(print(0, 0), "1970-01-01T00:00:00Z");
    assert_eq!(print(-1, 500_000_000), "1969-12-31T23:59:59.5Z");
    assert_eq!(print(951_782_400, 250_000_000), "2000-02-29T00:00:00.25Z");
    assert_eq!(print(1_791_279_000, 1), "2026-10-06T09:30:00.000000001Z");
}

#[test]
fn a_time_is_the_system_clocks_both_ways() {
    let before_1970 = std::time::UNIX_EPOCH - Duration::from_millis(1500);
    let time = Timestamp::from(before_1970);

    assert_eq!((time.seconds, time.nanos), (-2, 500_000_000));
    assert_eq!(time.to_system_time(), Some(before_1970));
}
